//! 歸一化敵意 fixture(RYOSYS-MVP §4.2;10.5 紀律:歸一化實現必帶單測)。
//!
//! 釘死四個敵意形:
//! ①設計輸出行以 `- `、`tb.v:6: ` 開頭(riv 實錄教訓)不受影響;
//! ②stat 表自帶 `+---`/`| ` 對齊行——prologue/epilogue 是結構切(位置在
//!   log 首尾),不吞中段 stat 表;
//! ③`.il` 第二行起出現 `# Generated by` 相似文字(設計內容)不被剝;
//! ④stdout 中段的 `Warning: ` 行(含 `values.v:33: Warning: …` 帶源路徑
//!   前綴形)必須原樣保留——它不是丟行白名單成員(§0-9:check Warning
//!   在 stdout 中段,是 golden 內容)。

use ry_difftest::{normalize_il, normalize_json, normalize_stdout};

#[test]
fn hostile_1_design_lines_with_dash_prefix_survive() {
    let text = "banner junk\n-- Running command `x' --\n-7div2=-3\ntb.v:6: some design line\n";
    let n = normalize_stdout(text);
    assert!(n.contains("-7div2=-3"), "設計行被吃: {n:?}");
    assert!(n.contains("tb.v:6: some design line"), "設計行被吃: {n:?}");
}

#[test]
fn hostile_2_stat_table_alignment_lines_not_swallowed() {
    let text = concat!(
        "-- Running command `stat' --\n",
        "=== top ===\n",
        "\n",
        "        +----------Local Count, excluding submodules.\n",
        "        | \n",
        "       20 wires\n",
        "End of script. Logfile hash: 120839f9be, time: 0.00s\n",
        "Yosys 0.70+179 trailing junk\n",
    );
    let n = normalize_stdout(text);
    assert!(n.contains("        +----------Local Count, excluding submodules."));
    assert!(n.contains("        | \n"), "stat 表 | 行必須逐字保留(含尾隨空格)");
    assert!(n.contains("       20 wires"));
    assert!(!n.contains("Logfile hash"), "epilogue 必須切");
    assert!(!n.contains("trailing junk"));
}

#[test]
fn hostile_3_second_generated_by_line_is_design_content() {
    let text = "# Generated by Yosys 0.70+179\nmodule \\m\n  attribute \\note \"# Generated by fake\"\nend\n";
    let n = normalize_il(text);
    assert!(n.contains("# Generated by fake"), "第二行起的相似前綴=設計內容,禁剝");
    assert!(n.starts_with("module \\m"));
}

#[test]
fn hostile_4_midstream_warning_lines_are_golden_content() {
    let text = concat!(
        "-- Running command `check' --\n",
        "2. Executing CHECK pass (checking for obvious problems).\n",
        "Checking module top...\n",
        "Warning: Wire top.\\out6 [3] is used but no driver.\n",
        "values.v:33: Warning: something else\n",
        "Found and reported 1 problems.\n",
    );
    let n = normalize_stdout(text);
    assert!(n.contains("Warning: Wire top.\\out6 [3] is used but no driver."));
    assert!(n.contains("values.v:33: Warning: something else"));
}

#[test]
fn no_banner_means_everything_is_prologue() {
    // 無 `-- Running command` 行:全部內容都屬 prologue(結構切以橫幅
    // 錨定;錨不在場=無中段可保)。行為=空串,不 panic、不發明內容。
    let text = "error before any command\n";
    assert_eq!(normalize_stdout(text), "");
}

#[test]
fn trailing_newline_split_element_is_not_content() {
    // ryosys 的 log_error 中止徑:無 epilogue、流以單個換行結束——
    // 分裂出的空元素不補行尾 byte(const_fold_func 對拍實錄)。
    let text = "-- Running command `x' --\n1. Executing JSON backend.\n";
    assert_eq!(normalize_stdout(text), "-- Running command `x' --\n1. Executing JSON backend.");
    // 觸 epilogue 的形(oracle 徑)不受影響:
    let text2 = "-- Running command `x' --\nA\nEnd of script. Logfile hash: 1, time: 0.00s\nZ\n";
    assert_eq!(normalize_stdout(text2), "-- Running command `x' --\nA");
    // 中段空行=內容:
    let text3 = "-- Running command `x' --\nA\n\nB\n";
    assert_eq!(normalize_stdout(text3), "-- Running command `x' --\nA\n\nB");
}

#[test]
fn il_first_line_must_be_generated_by() {
    // 非公約首行=斷言失敗(錄製/對拍管線出錯,靜默通過=假綠)。
    let r = std::panic::catch_unwind(|| normalize_il("module \\m\nend\n"));
    assert!(r.is_err());
}

#[test]
fn json_creator_line_dropped_rest_kept() {
    let text = "{\n  \"creator\": \"Yosys 0.70+179 (git sha1 ...)\",\n  \"modules\": {\n  }\n}\n";
    let n = normalize_json(text);
    assert!(!n.contains("creator"));
    assert!(n.contains("\"modules\""));
}
